import { useEffect, useRef, useState } from 'react';
import { Animated, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';

import { addWater, deleteWater, getWater } from '@/api/api';
import { NumberBoard } from '@/components/number-board';
import { PanelView } from '@/components/panel-view';
import Popup from '@/components/popup';
import { useAuth } from '@/context/AuthContext';

type WaterData = {
    userId: string;
    value: number;
    timestamp: number;
}

export default function WaterPage() {
    const { user } = useAuth();
    const [waterData, setWaterData] = useState<any>([]);
    const fetchWaterData = async () => {
        try {
            const result = await getWater({ userId: user.userId });
            setWaterData(result);
        } catch (error) {
            console.error('water 資料抓取失敗:', error);
        }
    };
    useEffect(() => {
        fetchWaterData();
    }, []);
    const userWeight = user.weight;
    const currentTimestamp = new Date();
    const currentYear = currentTimestamp.getFullYear();
    const currentMonth = currentTimestamp.getMonth() + 1;
    const currentDay = currentTimestamp.getDate();
    const currentMonthData: WaterData[] = [];
    const [dataForChart, setDataForChart] = useState<any>([]);
    const reverseWaterData = [...waterData].reverse();
    reverseWaterData.forEach((item) => {
        const date = new Date(item.timestamp * 1000);
        date.setHours(0, 0, 0, 0);
        const month = date.getMonth() + 1;

        if (month == currentMonth) {
            currentMonthData.unshift(item);
        }
    });
    const groupedCurrentMonthDataByDay = currentMonthData.reduce((grouped: WaterData[][], item: WaterData) => {
        const date = new Date(item.timestamp * 1000);
        const day = date.getDate();

        if (!grouped[day]) {
            grouped[day] = [];
        }
        grouped[day].unshift(item);

        return grouped;
    }, []);
    const [isAdd, setIsAdd] = useState(false);
    const [timeOfEdit, setTimeOfEdit] = useState(0);
    const [openWaterEditPopup, setOpenWaterEditPopup] = useState(false);
    const [numberBoardDefaultValue, setNumberBoardDefaultValue] = useState(waterData.length > 0 ? waterData[waterData.length - 1].value : 300);
    let currentConsumption = groupedCurrentMonthDataByDay[currentDay] ? groupedCurrentMonthDataByDay[currentDay].reduce<number>((total, item) => {
            return total + item.value;
    }, 0) : 0;
    let firstDailyTarget = userWeight * 30;
    let seccondDailyTarget = userWeight * 40;
    let firstTargetPercent = currentConsumption / firstDailyTarget * 100 >= 100 ? 100 : currentConsumption / firstDailyTarget * 100;
    let secondTargetPercent = currentConsumption / seccondDailyTarget * 100 >= 100 ? 100 : currentConsumption / seccondDailyTarget * 100;

    // const progressWidth = `${Math.min(parseFloat(secondTargetPercent.toFixed(1)), 100)}%` as any;
    const animatedWidth = useRef(new Animated.Value(0)).current;

    useEffect(() => {
        Animated.timing(animatedWidth, {
            toValue: currentConsumption, // 目標數值
            duration: 1000,               // 動畫持續時間 (毫秒)
            useNativeDriver: false,
        }).start();
    }, [currentConsumption]);

    const progressWidth = animatedWidth.interpolate({
        inputRange: [0, seccondDailyTarget],
        outputRange: ['0%', '100%'],
    });

    async function addAndGetWaterData(selectValue: number) {
        try {
            const today = new Date();
            const ms = today.getTime();
            await addWater({ userId: user.userId, value: selectValue, timestamp: Math.floor(ms / 1000) });

            const result = await getWater({ userId: user.userId });
            setWaterData(result);
            setNumberBoardDefaultValue(selectValue);
        } catch (err) {
            alert("請再試一次" + err);
        }
    }

    async function updateAndGetWaterData(selectValue: number) {
        try {
            // NoSQL的特性如果新增資料中的兩個key在資料表裡有一樣的兩個key，就會變成更新那筆資料
            await addWater({ userId: user.userId, value: selectValue, timestamp: timeOfEdit });

            const result = await getWater({ userId: user.userId });
            setWaterData(result);
            setNumberBoardDefaultValue(selectValue);
        } catch (err) {
            alert("請再試一次" + err);
        }
    }

    async function deleteAndGetWaterData(timestamp: number) {
        try {
            await deleteWater({ userId: user.userId, timestamp: timestamp });

            const result = await getWater({ userId: user.userId });
            setWaterData(result);
        } catch (err) {
            alert("請再試一次" + err);
        }
    }

	return (
        <PanelView>
            <ScrollView style={styles.container}>
                <Pressable
                    style={styles.insertArea}
                    onPress={() => {
                        setIsAdd(true);
                        setOpenWaterEditPopup(true);
                    }}
                >
                    <Text style={styles.addText} selectable={false}>
                        喝水:
                    </Text>
                    <View style={styles.progressBarContainer}>
                        <View style={styles.progressBarBackground}>
                            <Animated.View style={[styles.progressBarFill, { width: progressWidth }]}>
                                <Text style={styles.consumptionText} numberOfLines={1}>
                                    {currentConsumption}
                                </Text>
                            </Animated.View>
                        </View>
                    </View>
                </Pressable>
                {Object.keys(groupedCurrentMonthDataByDay).length > 0 && (
                    <View style={styles.otherArea}>
                        {Object.keys(groupedCurrentMonthDataByDay).reverse().map((dayKey) => {
                            let day = Number(dayKey);

                            return (
                                <View key={`list_daily_${currentMonth}_${day}`}>
                                    <View style={styles.dayHeader}>
                                        <Text style={styles.dayHeaderText} selectable={false}>
                                            {String(currentMonth).padStart(2, "0")}月{day}日
                                        </Text>
                                    </View>
                                    {groupedCurrentMonthDataByDay[day].map((item) => {
                                        const time = new Date(item.timestamp * 1000);
                                        const hhmm = time.toLocaleTimeString("zh-TW", {
                                            hour12: false,
                                            hour: "2-digit",
                                            minute: "2-digit"
                                        });

                                        return (
                                            <Pressable 
                                                style={({ pressed }) => [
                                                    styles.itemRow, 
                                                    { opacity: pressed ? 0.9 : 1 }
                                                ]}
                                                key={`daily_${currentMonth}_${day}_${item.timestamp}`}
                                                onPress={() => {
                                                    setIsAdd(false);
                                                    setTimeOfEdit(item.timestamp);
                                                    setOpenWaterEditPopup(true);
                                                }}
                                            >
                                                <View>
                                                    <View>
                                                        <Text style={styles.itemText} selectable={false}>{hhmm}</Text>
                                                    </View>
                                                    <View>  
                                                        <Text style={styles.itemText} selectable={false}>{item.value} ml</Text>
                                                    </View>
                                                </View>
                                                <Pressable 
                                                    style={({ pressed }) => [
                                                        styles.deleteButton,
                                                        { opacity: pressed ? 0.8 : 1 }
                                                    ]}
                                                    onPress={() => {
                                                        deleteAndGetWaterData(item.timestamp);
                                                    }}
                                                >
                                                    <Text style={styles.deleteButtonText} selectable={false}>刪除</Text>
                                                </Pressable>
                                            </Pressable>
                                        );
                                    })}
                                </View>
                            );
                        })}
                    </View>
                )}
            </ScrollView>

            <Popup controller={[openWaterEditPopup, setOpenWaterEditPopup]}>
                <NumberBoard
                    default={numberBoardDefaultValue}
                    setValue={isAdd ? addAndGetWaterData : updateAndGetWaterData}
                    float={false}
                    controller={[openWaterEditPopup, setOpenWaterEditPopup]}
                />
            </Popup>
        </PanelView>
    );
}

