import { Dispatch, ReactNode, SetStateAction } from 'react';
import { Modal, Pressable, StyleSheet } from 'react-native';

type PopupProps = {
    children: ReactNode;
    controller: [
        boolean,
        Dispatch<SetStateAction<boolean>>
    ];
}

export default function Popup(props: PopupProps) {
    const [visible, setVisible] = props.controller;

    return (
        <Modal
            animationType="none" // 可選 'slide' | 'fade' | 'none'
            transparent={true}   // 讓背景變半透明
            visible={visible}
        >
            <Pressable style={styles.overlay} onPress={() => setVisible(false)}>
                <Pressable style={styles.popupCard} onPress={() => setVisible(false)}>
                    {props.children}
                </Pressable>
            </Pressable>
        </Modal>
    );
}



const styles = StyleSheet.create({
    overlay: {
        flex: 1,
        backgroundColor: 'rgba(0, 0, 0, 0.5)',
        justifyContent: 'center',
        alignItems: 'center',
        cursor: 'auto',
    },
    popupCard: {
        width: '85%',
        height: '70%',
        alignItems: 'center',
        justifyContent: 'center',
        userSelect: 'none',
        cursor: 'auto',
    },
});
