import { PanelView } from '@/components/panel-view';
import { CameraView, useCameraPermissions } from 'expo-camera';
import { Image } from 'expo-image';
import { useRef, useState } from 'react';
import { Platform, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';

import Ionicons from '@expo/vector-icons/Ionicons';
import MaterialCommunityIcons from '@expo/vector-icons/MaterialCommunityIcons';

import { foodAnalyze } from '@/api/api';
import Popup from '@/components/popup';
import { isMobileBrowser } from '@/constants/tool';

type FoodItem =  {
    name: string;
    weight_g: number;
    calories: number;
    protein: number;
    carbs: number;
    fat: number;
    probability: number;
}

type FoodResults = {
    items: FoodItem[][];
}

export default function ProteinPage() {
    const [isClassifying, setIsClassifying] = useState<boolean>(false);
    const [openCameraWindow, setOpenCameraWindow] = useState<boolean>(false);
    const [permission, requestPermission] = useCameraPermissions();
    const cameraRef = useRef<CameraView>(null);
    const [isCameraActive, setIsCameraActive] = useState<boolean>(false);
    const [capturedImage, setCapturedImage] = useState<string | null>(null);
    const [results, setResults] = useState<FoodResults | null>(null);

    async function startCamera() {
        if (!permission?.granted) {
            const permissionResult = await requestPermission();
            if (!permissionResult.granted) {
                alert('需要相機權限才能使用拍照辨識！');
                return;
            }
        }
        setCapturedImage(null);
        setResults(null);
        setIsCameraActive(true);
    };

    async function captureAndClassify() {
        if (!cameraRef.current)
            return;

        try {
            const photo = await cameraRef.current.takePictureAsync({
                quality: 0.8,
            });

            if (!photo?.uri) return;

            setCapturedImage(photo.uri);
            setIsClassifying(true);
            setOpenCameraWindow(false);

            const formData = new FormData();

            if (Platform.OS === 'web') {
                const response = await fetch(photo.uri);
                const blob = await response.blob();
                formData.append('image', blob, 'food.jpg');
            } else {
                formData.append('image', {
                    uri: photo.uri,
                    name: 'food.jpg',
                    type: 'image/jpeg',
                } as any);
            }

            let result = await foodAnalyze(formData);
            
            if (result.error) {
                setResults({items: []});
            } else {
                setResults(result);
            }
        } catch (error) {
            console.error('辨識失敗:', error);
            setResults({items: []});
        } finally {
            setIsClassifying(false);
        }
    };

	return (
        <PanelView>
            <ScrollView style={styles.container}>
                <View style={styles.insertArea}>
                    <Pressable
                        style={styles.turnOnButton}
                        onPress={() => {
                            setOpenCameraWindow(true);
                            startCamera();
                        }}
                    >
                        <Text style={styles.turnOnText} selectable={false}>
                            <Ionicons name="camera-sharp" size={36}/>{' 開啟相機'}
                        </Text>
                    </Pressable>
                </View>
                <View style={styles.resultArea}>
                    <Text style={styles.result} selectable={false}>
                        辨識結果:
                    </Text>
                    <Text
                        style={[
                            styles.result,
                            { display: isClassifying ? 'flex' : 'none'},
                        ]}
                        selectable={false}

                    >
                        { isClassifying && (<Text><MaterialCommunityIcons name="robot-outline" size={20}/>{' 正在全力分析這張照片...'}</Text>) }
                    </Text>
                    <View>
                        {results?.items && results.items.length > 0 && (
                            <View style={styles.listContainer}>
                                {results.items.map((itemGroup: FoodItem[], index: number) => {
                                    const isLastGroup = index === results.items.length - 1;

                                    return (
                                        <View
                                            style={[styles.gridRow, !isLastGroup && styles.marginBottom5]}
                                        >
                                            {/* 序號欄 (col-span-1) */}
                                            <View style={styles.col1}>
                                                <Text style={styles.indexText} selectable={false}>{`${index + 1}.`}</Text>
                                            </View>

                                            {/* 內容欄 (col-span-10) */}
                                            <View style={styles.col2}>
                                                {itemGroup.map((v: FoodItem, i: number) => {
                                                    const probabilityPercent = Number((v.probability * 100).toFixed(1));
                                                    
                                                    const progressBarColor =
                                                        v.probability > 0.7
                                                            ? '#10b981'
                                                            : v.probability > 0.3
                                                            ? '#fb923c'
                                                            : '#dc2626';

                                                    return (
                                                        <View key={`${index}_${i}`} style={styles.itemBlock}>
                                                            <Text style={styles.infoText} selectable={false}>
                                                                {`${v.name}(${v.weight_g}g):\n${v.calories}大卡 (${v.protein}P ${v.carbs}C ${v.fat}F) ${probabilityPercent}%`}
                                                            </Text>

                                                            <View style={styles.progressTrack}>
                                                                <View
                                                                    style={[
                                                                        styles.progressBar,
                                                                        {
                                                                            width: `${probabilityPercent}%`,
                                                                            backgroundColor: progressBarColor,
                                                                        },
                                                                    ]}
                                                                />
                                                            </View>
                                                        </View>
                                                    );
                                                })}
                                            </View>
                                        </View>
                                    );
                                })}
                            </View>
                        )}

                        {results?.items.length === 0 && (
                            <View style={styles.errorContainer}>
                                <Text style={styles.errorText}>辨識失敗</Text>
                            </View>
                        )}

                        {capturedImage && (
                            <Image
                                source={{ uri: capturedImage }}
                                style={styles.capturedImage}
                                contentFit="contain"
                            />
                        )}
                    </View>
                </View>
                <Popup controller={[openCameraWindow, setOpenCameraWindow]}>
                    <View style={styles.popupContainer}>
                        <View style={styles.cameraContainer}>
                            <CameraView
                                ref={cameraRef}
                                style={styles.camera}
                            />
                        </View>
                        <Pressable
                            style={[
                                styles.captureButton,
                                { backgroundColor: isCameraActive ? '#b45309' : '#d1d5db' },
                            ]}
                            onPress={captureAndClassify}
                        >
                            <Text style={styles.captureButtonText}>
                                <Ionicons name="camera-sharp" size={36}/>{' 拍照並辨識'}
                            </Text>
                        </Pressable>
                    </View>
                </Popup>
            </ScrollView>
        </PanelView>
    );
}

