import { useState } from 'react';
import { ActivityIndicator, StyleSheet, Text, TextInput, TouchableOpacity, View } from 'react-native';

import { userLogin } from '@/api/api';
import { PanelView } from '@/components/panel-view';
import { useAuth } from '@/context/AuthContext';
import { version } from '../package.json';

export default function LoginPage() {
    const { signIn } = useAuth();
    const [userId, setUserId] = useState('');
    const [password, setPassword] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const handleLogin = async () => {
        if (!userId || !password) {
            setError('請輸入帳號與密碼');
            return;
        }

        setIsSubmitting(true);
        setError(null);

        try {
            // 1. 呼叫後端 API 驗證帳密
            const result = await userLogin({ userId, password });

            if (result.errorcode) {
                // API 失敗：顯示後端傳回的錯誤訊息
                setError(result.message || '帳號或密碼錯誤');
            } else {
                // 2. API 成功：設定登入狀態，並跳轉到主頁 (tabs)
                // 呼叫 await signIn() 後，_layout.tsx 的路由守衛會自動處理頁面跳轉
                await signIn(result.token, result);
            }
        } catch (err) {
            setError('網路連線失敗，請稍後再試');
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <PanelView>
            <View style={styles.container}>
                <View style={styles.loginContainer}>
                    <Text style={styles.label} selectable={false}>帳號:</Text>
                    <TextInput
                        style={styles.input}
                        value={userId}
                        onChangeText={setUserId}
                        placeholder="請輸入帳號"
                        placeholderTextColor="#9ca3af"
                        autoCapitalize="none"
                    />

                    <Text style={styles.label} selectable={false}>密碼:</Text>
                    <TextInput
                        style={styles.input}
                        value={password}
                        onChangeText={setPassword}
                        placeholder="請輸入密碼"
                        placeholderTextColor="#9ca3af"
                        secureTextEntry
                    />

                    {error && (
                        <Text style={styles.errorText}>{error}</Text>
                    )}

                    <TouchableOpacity
                        style={[styles.button, isSubmitting && styles.buttonDisabled]}
                        onPress={handleLogin}
                        disabled={isSubmitting}
                    >
                        {isSubmitting ? (
                            <ActivityIndicator color="#000" />
                        ) : (
                            <Text style={styles.buttonText} selectable={false}>登入</Text>
                        )}
                    </TouchableOpacity>

                    <View style={styles.footer}>
                        <TouchableOpacity 
                            onPress={() => alert('導覽')}
                            style={styles.footerLeft}
                        >
                            <Text style={styles.footerText}>導覽</Text>
                        </TouchableOpacity>

                        <Text style={[styles.footerText, styles.footerRight]} selectable={false}>
                            v{version}
                        </Text>
                    </View>
                </View>
            </View>
        </PanelView>
    );
}

const styles = StyleSheet.create({
    container: {
        backgroundColor: 'rgba(106, 114, 130, 0.7)',
        flex: 1,
        justifyContent: 'center',
        alignItems: 'center',
        height: '100%',
    },
    loginContainer: {
        width: '60%',
        backgroundColor: '#7e2a0c',
        borderRadius: 4,
        padding: 6,
    },
    label: {
        color: '#ffffff',
        fontSize: 16,
        userSelect: 'none',
    },
    input: {
        margin: 8,
        padding: 4,
        borderRadius: 4,
        backgroundColor: '#000000',
        color: '#ffffff',
        fontSize: 16,
    },
    errorText: {
        color: '#f87171',
        fontSize: 12,
        paddingHorizontal: 8,
        marginBottom: 8,
        userSelect: 'none',
    },
    button: {
        backgroundColor: '#ffffff',
        padding: 4,
        margin: 8,
        borderRadius: 4,
        alignItems: 'center',
    },
    buttonDisabled: {
        backgroundColor: '#9ca3af',
    },
    buttonText: {
        color: '#000000',
        fontSize: 16,
    },
    footer: {
        flexDirection: 'row',
        width: '100%',
        marginTop: 4,
    },
    footerLeft: {
        width: '50%',
    },
    footerRight: {
        width: '50%',
        textAlign: 'right',
    },
    footerText: {
        color: '#ffffff',
        fontSize: 16,
        userSelect: 'none',
    },
});
